import{_ as r,c as e,o,ae as t}from"./chunks/framework.U1Gow_7P.js";const b=JSON.parse('{"title":"🏡【田园筑梦】大型建筑激励计划 · 长期活动","description":"","frontmatter":{},"headers":[],"relativePath":"builder.md","filePath":"builder.md"}'),i={name:"builder.md"};function n(l,a,d,s,p,g){return o(),e("div",null,a[0]||(a[0]=[t('<h1 id="🏡【田园筑梦】大型建筑激励计划-·-长期活动" tabindex="-1">🏡【田园筑梦】大型建筑激励计划 · 长期活动 <a class="header-anchor" href="#🏡【田园筑梦】大型建筑激励计划-·-长期活动" aria-label="Permalink to &quot;🏡【田园筑梦】大型建筑激励计划 · 长期活动&quot;">​</a></h1><p align="center"><b>亲爱的建筑师们，为了将我们的田园世界建设得更加壮丽，</b><br><b>服务器现正式开启 <span style="color:#B8860B;font-size:1.2em;">「筑梦师扶持计划」</span></b><br> 无论你是想造一座城堡，还是复刻一个村落，服务器金币管够！ </p><hr><h2 id="🌟-核心机制-三步走战略" tabindex="-1">🌟 核心机制：三步走战略 <a class="header-anchor" href="#🌟-核心机制-三步走战略" aria-label="Permalink to &quot;🌟 核心机制：三步走战略&quot;">​</a></h2><p>本计划采用 <strong>“预支启动 → 建造报销 → 完工重奖”</strong> 的模式，确保你从开工到竣工全程无忧。</p><div style="background-color:#f5f2e6;padding:20px;border-radius:16px;margin:20px 0;border-left:6px solid #8B9A6E;"><h3 id="🚀-第一步-申请立项-预支启动金" tabindex="-1">🚀 第一步：申请立项 &amp; 预支启动金 <a class="header-anchor" href="#🚀-第一步-申请立项-预支启动金" aria-label="Permalink to &quot;🚀 第一步：申请立项 &amp; 预支启动金&quot;">​</a></h3><p>如果你有一个宏大的建筑计划（如大型庄园、哥特教堂、跨河桥梁群），但手头金币不足：</p><ol><li>填写立项问卷，附上你的<strong>设计草图</strong>或<strong>参考图</strong>以及<strong>大致预算</strong>。</li><li>审核通过后，<strong>立即预支最低 10万 金币</strong>的启动资金！</li></ol><h3 id="🧱-第二步-建造过程-实时报销" tabindex="-1">🧱 第二步：建造过程 &amp; 实时报销 <a class="header-anchor" href="#🧱-第二步-建造过程-实时报销" aria-label="Permalink to &quot;🧱 第二步：建造过程 &amp; 实时报销&quot;">​</a></h3><p>建造过程中，所有的<strong>常规建材</strong>（如木头、石头、玻璃等）花费，无需自己承担！</p><ol><li>建造期间，收集你需要报销的物资凭证（或截图库存）。</li><li>联系<strong>服主/管理员</strong>进行线下验收或核查。</li><li><strong>规则</strong>：只要是用于该建筑的合理建材消耗，<strong>全额报销</strong>！物资直接补货或按价补偿金币。</li></ol><h3 id="🏆-第三步-完工审核-终极大奖" tabindex="-1">🏆 第三步：完工审核 &amp; 终极大奖 <a class="header-anchor" href="#🏆-第三步-完工审核-终极大奖" aria-label="Permalink to &quot;🏆 第三步：完工审核 &amp; 终极大奖&quot;">​</a></h3><p>建筑主体完工后，真正的奖励才刚刚开始：</p><ol><li><strong>联系管理员</strong>进行最终验收。</li><li>全体玩家根据建筑的<strong>规模、细节、创意</strong>进行评分。</li><li><strong>上不封顶的终奖</strong>： <ul><li><strong>基础奖励</strong>：根据建筑体量，直接发放 <strong>20万 ~ 800万</strong> 金币。</li><li><strong>地标加成</strong>：若建筑成为服务器公认地标，额外追加 <strong>50万</strong> 金币。</li><li><strong>细节狂魔</strong>：内饰精美、环境搭配得当，奖励翻倍！</li></ul></li></ol></div><hr><h2 id="💰-为什么说-上不封顶" tabindex="-1">💰 为什么说“上不封顶”？ <a class="header-anchor" href="#💰-为什么说-上不封顶" aria-label="Permalink to &quot;💰 为什么说“上不封顶”？&quot;">​</a></h2><div style="display:flex;justify-content:space-around;text-align:center;margin:30px 0;"><div style="background:linear-gradient(145deg, #e6d5b8, #f5e8c9);padding:20px;border-radius:20px;width:45%;box-shadow:5px 5px 15px rgba(0,0,0,0.2);"><h3 style="color:#5a3e1b;">📦 报销无上限</h3><p>只要你盖，只要是用在建筑上的合理建材，统统报销。</p></div><div style="background:linear-gradient(145deg, #d4c3a3, #e8d9bc);padding:20px;border-radius:20px;width:45%;box-shadow:5px 5px 15px rgba(0,0,0,0.2);"><h3 style="color:#5a3e1b;">🏅 奖励无上限</h3><p>你建得越大、越精美，奖励越高。建造一座城市，奖励就可能高达千万。<br><b>只要你的创意够大，服主的金币库就够深！</b></p></div></div><hr><h2 id="📝-如何申请" tabindex="-1">📝 如何申请？ <a class="header-anchor" href="#📝-如何申请" aria-label="Permalink to &quot;📝 如何申请？&quot;">​</a></h2><p>只需要简单两步，即可开启你的筑梦之旅：</p><div style="background-color:#e6f0da;padding:30px;border-radius:30px;text-align:center;margin:30px 0;border:3px dashed #6b8e4c;"><h3 id="✍️-第一步-填写立项问卷-耗时2分钟" tabindex="-1">✍️ 第一步：填写立项问卷（耗时2分钟） <a class="header-anchor" href="#✍️-第一步-填写立项问卷-耗时2分钟" aria-label="Permalink to &quot;✍️ 第一步：填写立项问卷（耗时2分钟）&quot;">​</a></h3><p>告诉我你的想法、需要的预算和大致规模</p><p align="center"><a href="https://docs.qq.com/form/page/DR2xCSEx3dGJETGxH" style="background-color:#8B9A6E;color:white;padding:15px 40px;text-decoration:none;border-radius:50px;font-size:1.5em;font-weight:bold;display:inline-block;box-shadow:0 5px 15px rgba(0,0,0,0.2);">👉 点击此处填写申请问卷 👈</a></p><h3 id="✅-第二步-等待审核" tabindex="-1">✅ 第二步：等待审核 <a class="header-anchor" href="#✅-第二步-等待审核" aria-label="Permalink to &quot;✅ 第二步：等待审核&quot;">​</a></h3><p>提交问卷后，服主/管理员会尽快联系你，对接预支款项和具体细节</p></div><hr><h2 id="⚠️-活动规则" tabindex="-1">⚠️ 活动规则 <a class="header-anchor" href="#⚠️-活动规则" aria-label="Permalink to &quot;⚠️ 活动规则&quot;">​</a></h2><div style="background-color:#f9eed7;padding:20px;border-radius:16px;border:1px solid #d4a76a;margin:20px 0;"><ul><li><strong>专款专用</strong>：预支和报销的金币/物资必须用于申请的建筑项目。</li><li><strong>进度汇报</strong>：超大型建筑建议每周发一次进度图，以便管理员跟踪报销。</li></ul></div><hr><p align="center" style="font-size:1.3em;background:linear-gradient(135deg, #f5e6d3, #faf0e1);padding:25px;border-radius:40px;margin-top:30px;"> 🌾 <b>还等什么？拿起你的方块，实现那个一直想盖却没敢动工的计划吧！</b><br><span style="color:#5e3a0c;">这片田园等待你的地标诞生！</span></p>',18)]))}const c=r(i,[["render",n]]);export{b as __pageData,c as default};
